datatype State = THINKING | HUNGRY | EATING

class TicketSystem {
    var ticket: int
    var serving: int
    var states: array<State>
    var t_local: array<int>
    const numPhil: int

    predicate Valid()
      reads this, states, t_local
    {
        numPhil > 0 &&
        states.Length == numPhil &&
        t_local.Length == numPhil &&
        StateInvariant() &&
        MutualExclusion()
    }

    predicate MutualExclusion()
      reads this, states, t_local
      requires states.Length == numPhil && t_local.Length == numPhil
    {
        forall i, j :: 0 <= i < numPhil && 0 <= j < numPhil && states[i] == EATING && states[j] == EATING ==> i == j
    }

    predicate StateInvariant()
      reads this, states, t_local
      requires states.Length == numPhil && t_local.Length == numPhil
    {
        ticket >= serving &&
        (forall i :: 0 <= i < numPhil && (states[i] == HUNGRY || states[i] == EATING) ==> serving <= t_local[i] < ticket) &&
        (forall i, j :: 0 <= i < numPhil && 0 <= j < numPhil && i != j && (states[i] == HUNGRY || states[i] == EATING) && (states[j] == HUNGRY || states[j] == EATING) ==> t_local[i] != t_local[j]) &&
        (forall i :: 0 <= i < numPhil && states[i] == EATING ==> t_local[i] == serving)
    }

    constructor (n: int)
      requires n > 0
      ensures Valid()
    {
        numPhil := n;
        ticket := 0;
        serving := 0;
        states := new State[n](_ => THINKING);
        t_local := new int[n](_ => 0);
    }

    method Request(philId: int)
      requires Valid()
      requires 0 <= philId < numPhil
      requires states[philId] == THINKING
      modifies this, states, t_local
      ensures Valid()
    {
        states[philId] := HUNGRY;
        t_local[philId] := ticket;
        ticket := ticket + 1;
    }

    method Enter(philId: int)
      requires Valid()
      requires 0 <= philId < numPhil
      requires states[philId] == HUNGRY
      requires serving == t_local[philId]
      modifies this, states
      ensures Valid()
    {
        states[philId] := EATING;
    }

    method Leave(philId: int)
      requires Valid()
      requires 0 <= philId < numPhil
      requires states[philId] == EATING
      modifies this, states
      ensures Valid()
    {
        states[philId] := THINKING;
        serving := serving + 1;
    }
}

