import hashlib
content = '''// ============================================================================
// Ticket System - Formal Implementation in Dafny
// ============================================================================
// This specification formalizes a Ticket-based Mutual Exclusion System.
// A fixed number of philosophers compete for exclusive access to a shared 
// resource (a kitchen). To avoid conflict, a ticket dispenser grants numbered 
// tickets in sequential order, and only the philosopher whose ticket matches 
// the current \"serving\" display may enter.

// The possible states of a philosopher in the system:
// - THINKING: The philosopher is not currently trying to enter the kitchen.
// - HUNGRY: The philosopher has requested a ticket and is waiting for their turn.
// - EATING: The philosopher\'s ticket was called, and they are in the kitchen.
datatype State = THINKING | HUNGRY | EATING

class TicketSystem {
    // ------------------------------------------------------------------------
    // System State Variables
    // ------------------------------------------------------------------------

    // ticket: The next available ticket number to be dispensed.
    var ticket: int

    // serving: The ticket number currently allowed to enter the kitchen.
    var serving: int

    // states: An array tracking the current state (THINKING, HUNGRY, or EATING) 
    // of each philosopher. Indexed from 0 to numPhil - 1.
    var states: array<State>

    // t_local: An array holding the ticket number pulled by each philosopher.
    // Meaningful only if the philosopher\'s state is HUNGRY or EATING.
    var t_local: array<int>

    // numPhil: The total number of philosophers in the system. 
    // This is part of the static system configuration.
    const numPhil: int

    // ------------------------------------------------------------------------
    // Invariants & Safety Properties
    // ------------------------------------------------------------------------

    // Valid: A composite predicate that asserts the structural integrity of 
    // the arrays, and ensures that the system maintains both the state 
    // invariant and mutual exclusion properties.
    predicate Valid()
      reads this, states, t_local
    {
        numPhil > 0 &&
        states.Length == numPhil &&
        t_local.Length == numPhil &&
        StateInvariant() &&
        MutualExclusion()
    }

    // MutualExclusion: The primary safety property.
    // Asserts that no two distinct philosophers can be in the EATING state 
    // at the same time.
    predicate MutualExclusion()
      reads this, states, t_local
      requires states.Length == numPhil && t_local.Length == numPhil
    {
        forall i, j :: 0 <= i < numPhil && 0 <= j < numPhil && states[i] == EATING && states[j] == EATING ==> i == j
    }

    // StateInvariant: Auxiliary inductive invariants required to prove MutualExclusion.
    predicate StateInvariant()
      reads this, states, t_local
      requires states.Length == numPhil && t_local.Length == numPhil
    {
        // 1. The ticket dispenser counter is always >= the serving counter.
        ticket >= serving &&
        // 2. Any hungry/eating philosopher holds a ticket between the serving 
        //    counter (inclusive) and the ticket dispenser counter (exclusive).
        (forall i :: 0 <= i < numPhil && (states[i] == HUNGRY || states[i] == EATING) ==> serving <= t_local[i] < ticket) &&
        // 3. No two hungry/eating philosophers hold the same ticket number.
        (forall i, j :: 0 <= i < numPhil && 0 <= j < numPhil && i != j && (states[i] == HUNGRY || states[i] == EATING) && (states[j] == HUNGRY || states[j] == EATING) ==> t_local[i] != t_local[j]) &&
        // 4. Any eating philosopher\'s ticket matches the serving counter exactly.
        (forall i :: 0 <= i < numPhil && states[i] == EATING ==> t_local[i] == serving)
    }

    // ------------------------------------------------------------------------
    // Constructor & Transitions
    // ------------------------------------------------------------------------

    // Constructor: Initializes the ticket system.
    // Sets ticket and serving counters to 0, and all philosophers to THINKING.
    constructor (n: int)
      requires n > 0
      ensures Valid()
    {
        numPhil := n;
        ticket := 0;
        serving := 0;

        // Initialize arrays using lambda expressions mapping index \'i\' to the initial value.
        states := new State[n](i => THINKING);
        t_local := new int[n](i => 0);
    }

    // Request: A THINKING philosopher takes the next available ticket, becoming HUNGRY.
    method Request(philId: int)
      requires Valid()
      // Ensure the philosopher ID is valid
      requires 0 <= philId < numPhil
      // The philosopher must currently be THINKING to request a ticket
      requires states[philId] == THINKING
      modifies this, states, t_local
      ensures Valid()
    {
        states[philId] := HUNGRY;
        t_local[philId] := ticket;
        // Increment the ticket dispenser for the next requester
        ticket := ticket + 1;
    }

    // Enter: A HUNGRY philosopher whose ticket matches \'serving\' transitions to EATING.
    method Enter(philId: int)
      requires Valid()
      requires 0 <= philId < numPhil
      // The philosopher must be waiting (HUNGRY)
      requires states[philId] == HUNGRY
      // The philosopher\'s ticket must exactly match the \'serving\' display
      requires serving == t_local[philId]
      modifies this, states
      ensures Valid()
    {
        states[philId] := EATING;
    }

    // Leave: An EATING philosopher transitions back to THINKING and increments \'serving\'.
    method Leave(philId: int)
      requires Valid()
      requires 0 <= philId < numPhil
      // The philosopher must be currently EATING
      requires states[philId] == EATING
      modifies this, states
      ensures Valid()
    {
        states[philId] := THINKING;
        // Increment the \'serving\' counter to allow the next ticket holder in
        serving := serving + 1;
    }
}
'''
